{"command":"./.venv/bin/python3 - <<'EOF'
import json, collections
for name in ('base-debug','base-batch'):
    paths = collections.Counter(); nats = collections.Counter(); sets = collections.Counter()
    aw = 0
    with open(f'Resources/features/f-428/runs/P12.7/{name}.jsonl') as f:
        for line in f:
            r = json.loads(line)
            sets[r['set']] += 1
            if r['auto'] and not r['correct']:
                aw += 1
                nats[len(r['atoms'])] += 1
                for a in r['atoms']:
                    paths[a['path']] += 1
    print(name, 'sets:', dict(sets), 'autoWrong:', aw, 'atoms/line:', dict(nats), 'paths:', dict(paths))
EOF","i":"Checking path values and atom counts"}

