		Console.WriteLine();
		Console.WriteLine("Usage:");
		Console.WriteLine("  census <trace.jsonl>");
		Console.WriteLine("      Classify every auto-wrong line (auto == true && correct == false) of a");
		Console.WriteLine("      debug or batch HoldoutGate trace by relation (accepted row vs key row)");
		Console.WriteLine("      and site. TSV on stdout, relation x site summary on stderr.");
		Console.WriteLine();
		Console.WriteLine("  pairs <census-tsv> <trace.jsonl>");
		Console.WriteLine("      For each census row with blocker=window and route compound|other, emit");
		Console.WriteLine("      the parsedName head and the key head words. TSV on stdout.");
		Console.WriteLine();
		Console.WriteLine("Exits 1 on a missing file, a refused trace set (D-029), or a bad invocation.");
	}
}
