/// <summary>
/// The census verdict for one auto-wrong line: exactly one relation (accepted row vs key row) and
/// exactly one site (where the line was accepted). The TSV column order is the property order.
/// </summary>
public sealed record ClassificationResult
{
	/// <summary>Holdout identity of the line.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Line index within the recipe.</summary>
	public int LineIndex { get; init; }

	/// <summary>Trace set (<c>debug</c> or <c>batch</c>).</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Relation class: no-label, pack-unit-state, compound-head-lost, state-mismatch, row-choice-tier, same-head-other-qualifier, sibling-food, or other.</summary>
	public string Relation { get; init; } = string.Empty;

	/// <summary>Site: reuse, override, curated, or ranker.</summary>
	public string Site { get; init; } = string.Empty;

	/// <summary>For site=override: <c>yes</c>/<c>no</c> — whether the normalised rawText is a key in <c>exact-overrides.json</c>; empty otherwise.</summary>
	public string OverrideKey { get; init; } = string.Empty;

	/// <summary>Accepted row data type (tier).</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>Key row data type (tier).</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>Accepted row <c>FoodState</c> mask (state + satisfiers), as the enum's flag string.</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>Key row <c>FoodState</c> mask (state + satisfiers), as the enum's flag string.</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name, verbatim.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>The key head phrase (head term plus non-state leading words), singularised, space-joined.</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>Accepted row description, verbatim.</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>Key row description, verbatim.</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>The raw recipe line, verbatim.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>For relation=other: the trace field whose absence forced the class; empty otherwise.</summary>
	public string MissingField { get; init; } = string.Empty;

	/// <summary>For relation=row-choice-tier: which tier is higher, <c>key</c> or <c>accepted</c>; empty otherwise.</summary>
	public string HigherTier { get; init; } = string.Empty;

	/// <summary>For relation=same-head-other-qualifier: the qualifier words present on one side only; empty otherwise.</summary>
	public string QualifierDiff { get; init; } = string.Empty;
}
