{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — relation (accepted row vs key row) and site
/// (where the line was accepted) — using the production helpers only (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/>, <see cref="IngredientLineResolver.ShouldReuse(string, string)"/>
/// and <see cref="IngredientLineResolver.SingularizeToken"/>. No matcher logic is copied here.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token state probes (CA1861: no constant arrays as arguments).
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The key set of <c>exact-overrides.json</c>.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>Relation: the expected label is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw line, the key row is canned, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key's head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head, state and tier agree; only the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds, or a field the rule needs is missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker path without reuse.</summary>
	public const string SiteRanker = "ranker";

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line. The first relation rule that holds wins (brief §4 order);
	/// <see cref="ClassificationResult.MissingField"/> names a trace field a rule needed but the line lacked.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is null when the atom's path is not one of ranker/override/curated.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;
		var site = ClassifySite(line, atom, out var overrideKey);

		var keyDesc = First(line.ExpectedDescriptions);
		var accDesc = First(line.ActualDescriptions);
		var keyType = First(line.ExpectedDataTypes);
		var accType = First(line.ActualDataTypes);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var accTokens = _normalizer.NormalizeToTokens(accDesc);
		var keyState = CombinedState(keyTokens);
		var accState = CombinedState(accTokens);

		var keyHeadParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyType));
		var accHeadParsed = string.IsNullOrWhiteSpace(accDesc)
			? new ParsedFdcDescription(string.Empty, [], null)
			: FdcDescriptionParser.Parse(accDesc, DatasetOf(accType));

		var headKey = SingularPhrase(keyHeadParsed.HeadTerm);
		var headAcc = SingularPhrase(accHeadParsed.HeadTerm);
		var parsedTokens = SingularPhrase(parsedName);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		string relation;
		string? missingField = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = NoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (accState & FoodState.Canned) == FoodState.None)
		{
			relation = PackUnitState;
		}
		else if (keyPhrase.Count >= 2
			&& parsedTokens.Count == 1
			&& string.Equals(parsedTokens[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = CompoundHeadLost;
		}
		else if (HeadsAgree(headKey, headAcc))
		{
			if (keyState != accState)
			{
				relation = StateMismatch;
			}
			else if (string.IsNullOrWhiteSpace(keyType) || string.IsNullOrWhiteSpace(accType))
			{
				relation = Other;
				missingField = string.IsNullOrWhiteSpace(accType) ? "actualDataTypes" : "expectedDataTypes";
			}
			else if (!string.Equals(keyType, accType, StringComparison.OrdinalIgnoreCase))
			{
				relation = RowChoiceTier;
			}
			else
			{
				relation = SameHeadOtherQualifier;
			}
		}
		else
		{
			relation = SiblingFood;
		}

		var qualifierDiff = relation == SameHeadOtherQualifier
			? QualifierDiff(keyHeadParsed.Qualifiers, accHeadParsed.Qualifiers)
			: null;

		return new ClassificationResult(
			line.HoldoutId,
			line.LineIndex,
			line.Set,
			relation,
			site,
			overrideKey,
			accType,
			keyType,
			accState.ToString(),
			keyState.ToString(),
			parsedName,
			string.Join(' ', keyPhrase),
			accDesc,
			keyDesc,
			line.RawText,
			missingField,
			qualifierDiff,
			TierDirection(accType, keyType));
	}

	/// <summary>
	/// The key's head phrase: the leading normalised tokens of the key description, cut before the first
	/// token the production state machinery recognises as a state word (a <see cref="FdcLexicon.ModifierWords"/>
	/// member, or a token <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/> /
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/> flags on its own).
	/// "Bread, crumbs, dry, grated, plain" → <c>[bread, crumbs]</c>; "Nuts, almonds, blanched" → <c>[nut, almond]</c>.
	/// </summary>
	/// <param name="keyTokens">The normalised key-description tokens.</param>
	/// <returns>The head-phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (IsStateWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The state mask the matcher would compute for a description: <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/>
	/// OR <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/> on the normalised tokens
	/// (the same composition <c>FdcMatcher</c> feeds into <c>StateAgrees</c>).
	/// </summary>
	/// <param name="tokens">The normalised description tokens.</param>
	/// <returns>The combined state mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Whether the production resolver's exact-phrase reuse rule (<see cref="IngredientLineResolver.ShouldReuse(string, string)"/>)
	/// would link <paramref name="parsedName"/> to <paramref name="linkedIngredientId"/>.
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>True when the reuse rule says the two name the same phrase.</returns>
	public static bool ReuseRuleLinks(string parsedName, string linkedIngredientId) =>
		IngredientLineResolver.ShouldReuse(Parsing.IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);

	private static string? ClassifySite(TraceLine line, TraceAtom? atom, out string? overrideKey)
	{
		overrideKey = null;
		if (atom is null)
		{
			return null;
		}

		if (atom.Path.Equals("override", StringComparison.OrdinalIgnoreCase))
		{
			overrideKey = null; // filled by the caller's key index below
			return SiteOverride;
		}

		if (atom.Path.Equals("curated", StringComparison.OrdinalIgnoreCase))
		{
			return SiteCurated;
		}

		if (atom.Path.Equals("ranker", StringComparison.OrdinalIgnoreCase))
		{
			return atom.Reused ? SiteReuse : SiteRanker;
		}

		return null;
	}

	private string? OverrideKeyFor(TraceLine line)
	{
		var raw = line.RawText.Trim();
		var paren = raw.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			raw = raw[..paren].Trim();
		}

		// Lowercase folding mirrors FdcMatcher's override lookup (nameClean = StripFromParenthesis(...).Trim().ToLowerInvariant()).
		return _overrideKeys.Contains(raw.ToLowerInvariant()) ? "yes" : "no";
	}

	private static bool HeadsAgree(IReadOnlyList<string> a, IReadOnlyList<string> b) =>
		a.Count == b.Count && a.Zip(b).All(p => string.Equals(p.First, p.Second, StringComparison.OrdinalIgnoreCase));

	private static bool IsStateWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		return FdcMatcher.ExtractCandidateState([token]) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers([token]) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static (IReadOnlyList<string> KeyOnly, IReadOnlyList<string> AcceptedOnly) QualifierDiff(
		IReadOnlyList<string> keyQualifiers,
		IReadOnlyList<string> accQualifiers)
	{
		var key = keyQualifiers.Select(IngredientLineResolver.SingularizeToken).ToHashSet(StringComparer.OrdinalIgnoreCase);
		var acc = accQualifiers.Select(IngredientLineResolver.SingularizeToken).ToHashSet(StringComparer.OrdinalIgnoreCase);
		var keyOnly = key.Where(q => !acc.Contains(q)).OrderBy(q => q, StringComparer.OrdinalIgnoreCase).ToArray();
		var accOnly = acc.Where(q => !key.Contains(q)).OrderBy(q => q, StringComparer.OrdinalIgnoreCase).ToArray();
		return (keyOnly, accOnly);
	}

	private static string? TierDirection(string accType, string keyType)
	{
		if (string.IsNullOrWhiteSpace(accType) || string.IsNullOrWhiteSpace(keyType)
			|| string.Equals(accType, keyType, StringComparison.OrdinalIgnoreCase))
		{
			return null;
		}

		return TierRank(keyType) > TierRank(accType) ? "key" : "accepted";
	}

	private static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	private static FdcDataset DatasetOf(string? dataType) =>
		Enum.TryParse<FdcDataset>(dataType, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static string First(IReadOnlyList<string> values) =>
		values.Count > 0 && !string.IsNullOrWhiteSpace(values[0]) ? values[0] : string.Empty;
}
