{"content":"using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Relation classes, in the brief's first-that-holds order (F-428 P12.13 §4).</summary>
public static class Relations
{
	/// <summary>Expected label empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Raw line carries a can/jar unit; the key row is Canned and the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>The key head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Head terms agree after singularising; the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Head terms and state agree; the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Head terms agree and nothing above holds; the qualifier words differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Nothing above held, or a relation check needed a field the trace lacks.</summary>
	public const string Other = "other";
}

/// <summary>Decision sites (F-428 P12.13 §4).</summary>
public static class Sites
{
	/// <summary>Ranker path with a reuse.</summary>
	public const string Reuse = "reuse";

	/// <summary>Override path.</summary>
	public const string Override = "override";

	/// <summary>Curated path.</summary>
	public const string Curated = "curated";

	/// <summary>Ranker path without a reuse.</summary>
	public const string Ranker = "ranker";
}

/// <summary>
/// Classifies one auto-wrong trace line on the two axes the P12.7 census could not: the relation
/// between the accepted row and the labelled (key) row, and the decision site. Every food-side
/// computation calls the production helpers (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> and <see cref="IngredientLineResolver.ShouldReuse"/>.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token state checks: ExtractCandidateState/
	// ExtractCandidateSatisfiers take IReadOnlyList<string>, and the runner is single-threaded.
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The key set of <c>exact-overrides.json</c>.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line. The first relation that holds wins (brief §4 order 1–8);
	/// a relation check that needs a field the trace lacks yields <see cref="Relations.Other"/> with
	/// <see cref="ClassificationResult.MissingField"/> named (brief §8).
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		var parsedNameTokens = SingularPhrase(atom?.ParsedName ?? string.Empty);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var relation = string.Empty;
		var missingField = (string?)null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = Relations.NoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = Relations.PackUnitState;
		}
		else if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = Relations.CompoundHeadLost;
		}
		else if (keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase))
		{
			if (keyState != acceptedState)
			{
				relation = Relations.StateMismatch;
			}
			else if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				relation = Relations.Other;
				missingField = string.IsNullOrWhiteSpace(acceptedTier) ? "actualDataTypes" : "expectedDataTypes";
			}
			else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				relation = Relations.RowChoiceTier;
			}
			else
			{
				relation = Relations.SameHeadOtherQualifier;
				var keyQualifiers = SingularPhraseList(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
				var acceptedQualifiers = SingularPhraseList(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);
				keyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
				acceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
			}
		}
		else
		{
			relation = Relations.SiblingFood;
		}

		var site = string.Empty;
		var overrideKey = string.Empty;
		if (atom is not null)
		{
			if (atom.Path.Equals("override", StringComparison.OrdinalIgnoreCase))
			{
				site = Sites.Override;
				overrideKey = _overrideKeys.Contains(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no";
			}
			else if (atom.Path.Equals("curated", StringComparison.OrdinalIgnoreCase))
			{
				site = Sites.Curated;
			}
			else if (atom.Path.Equals("ranker", StringComparison.OrdinalIgnoreCase))
			{
				site = atom.Reused ? Sites.Reuse : Sites.Ranker;
			}
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key head phrase: the key description's normalized tokens up to the first token the
	/// production state machinery or the <c>modifier-words.json</c> lexicon treats as a state/modifier
	/// word. "Bread, crumbs, dry, grated, plain" → <c>[bread, crumbs]</c>; "Nuts, almonds, blanched"
	/// → <c>[nut, almond]</c>. No new lexicon: the stop set is the production one.
	/// </summary>
	/// <param name="keyTokens">The key description's <see cref="FdcNormalizer.NormalizeToTokens"/> output.</param>
	/// <returns>The head phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (IsStateOrModifierWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The state mask the matcher sees on a description: <see cref="FdcMatcher.ExtractCandidateState"/>
	/// ∪ <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> — the same composition
	/// <c>FdcMatcher</c> feeds <c>StateAgrees</c> (FdcMatcher.cs:1155–1157).
	/// </summary>
	/// <param name="tokens">The description's normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// The raw-line normalization the override lookup applies (FdcMatcher.cs:165): cut at the first
	/// parenthesis, trim, lowercase. <c>StripFromParenthesis</c> itself is private, so the cut is
	/// reproduced here and the key set is the production <c>exact-overrides.json</c> (brief §4).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The normalized lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);
#pragma warning disable CA1308 // Reason: parity with FdcMatcher's override lookup (FdcMatcher.cs:165).
		var lowered = rawText.ToLowerInvariant();
#pragma warning restore CA1308
		var paren = lowered.IndexOf('(', StringComparison.Ordinal);
		return (paren >= 0 ? lowered[..paren] : lowered).Trim();
	}

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule (<see cref="IngredientLineResolver.ShouldReuse"/>)
	/// would link <paramref name="parsedName"/> to <paramref name="linkedIngredientId"/>.
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>True when the production rule reuses the linked master for this name.</returns>
	public static bool ReuseRuleLinks(string parsedName, string linkedIngredientId) =>
		IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);

	private static string First(IReadOnlyList<string> values) =>
		values.Count > 0 && !string.IsNullOrWhiteSpace(values[0]) ? values[0] : string.Empty;

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private bool IsStateOrModifierWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}
}
