{"content":"using System.Globalization;
using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: reads one HoldoutGate trace, classifies every <c>auto &amp;&amp; !correct</c>
/// line, and writes the TSV to <see cref="OutputWriters.Output"/> with the relation × site summary
/// on <see cref="OutputWriters.Error"/>. Refuses any trace whose records are not <c>debug</c> or
/// <c>batch</c> (D-029 — no sealed read).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (string.IsNullOrEmpty(_options.Command))
		{
			writers.Error.WriteLine("unusable arguments; expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'");
			return 1;
		}

		if (!File.Exists(_options.TracePath))
		{
			writers.Error.WriteLine($"trace file not found: {_options.TracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !l.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !l.Set.Equals("batch", StringComparison.OrdinalIgnoreCase));
		if (refused is not null)
		{
			writers.Error.WriteLine($"refused: trace record {refused.HoldoutId}#{refused.LineIndex} has set '{refused.Set}'; only debug and batch traces are classified (D-029)");
			return 1;
		}

		return _options.Command.Equals(CommandLineArgumentParser.PairsCommand, StringComparison.OrdinalIgnoreCase)
			? await RunPairsAsync(lines, cancellationToken).ConfigureAwait(false)
			: await RunCensusAsync(lines, cancellationToken).ConfigureAwait(false);
	}

	private async Task<int> RunCensusAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		var results = new List<ClassificationResult>(lines.Count);
		var unknownSite = 0;

		foreach (var line in lines)
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (!line.Auto || line.Correct)
			{
				continue;
			}

			var result = classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				unknownSite++;
				writers.Error.WriteLine($"unknown atom path '{AtomPathOf(line)}' on {line.HoldoutId}#{line.LineIndex}; cannot determine the site");
				continue;
			}

			results.Add(result);
		}

		WriteTsv(results);
		WriteSummary(lines, results);

		if (unknownSite > 0)
		{
			return 1;
		}

		return 0;
	}

	private async Task<int> RunPairsAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		if (!File.Exists(_options.CensusTsvPath))
		{
			writers.Error.WriteLine($"census tsv not found: {_options.CensusTsvPath}");
			return 1;
		}

		var wanted = new HashSet<(string HoldoutId, int LineIndex)>(StringComparer.OrdinalIgnoreCase);
		foreach (var row in ReadCensusRows(_options.CensusTsvPath))
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (row.Blocker.Equals("window", StringComparison.OrdinalIgnoreCase)
				&& (row.Route.Equals("compound", StringComparison.OrdinalIgnoreCase) || row.Route.Equals("other", StringComparison.OrdinalIgnoreCase)))
			{
				wanted.Add((row.HoldoutId, row.LineIndex));
			}
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex), StringComparer.OrdinalIgnoreCase);
		var emitted = 0;
		writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		foreach (var (holdoutId, lineIndex) in wanted.OrderBy(k => k.HoldoutId, StringComparer.OrdinalIgnoreCase).ThenBy(k => k.LineIndex))
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				writers.Error.WriteLine($"pairs: census row {holdoutId}#{lineIndex} not found in the trace");
				continue;
			}

			var parsedNameHead = string.Join(' ', FoldName(line.Atoms.Count > 0 ? line.Atoms[0].ParsedName : string.Empty));
			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(FdcNormalizerSingleton.Normalize(keyDesc)));
			writers.Output.WriteLine($"{Sanitize(holdoutId)}\t{lineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
			emitted++;
		}

		writers.Error.WriteLine($"pairs: {emitted} of {wanted.Count} window compound/other rows emitted");
		return 0;
	}

	private void WriteTsv(IReadOnlyList<ClassificationResult> results)
	{
		writers.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex.ToString(CultureInfo.InvariantCulture),
				Sanitize(r.Set),
				Sanitize(r.Relation),
				Sanitize(r.Site),
				Sanitize(r.OverrideKey),
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				Sanitize(r.AcceptedState),
				Sanitize(r.KeyState),
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}
	}

	private void WriteSummary(IReadOnlyList<TraceLine> lines, IReadOnlyList<ClassificationResult> results)
	{
		var set = lines.Count > 0 ? lines[0].Set : string.Empty;
		writers.Error.WriteLine($"autoWrongCensus set={set} traced={lines.Count} autoWrong={results.Count}");
		writers.Error.WriteLine("relation\tsite\tcount");
		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation).ThenBy(g => g.Key.Site))
		{
			writers.Error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={other}/{results.Count} ({(results.Count > 0 ? other * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key);
		if (missing.Any())
		{
			writers.Error.WriteLine("missing fields: " + string.Join(", ", missing.Select(g => $"{g.Key}={g.Count()}")));
		}

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			writers.Error.WriteLine($"overrideKey yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");
		}

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			var shouldReuseFalse = 0;
			var checkedCount = 0;
			foreach (var r in reuseLines)
			{
				var slug = IngredientLineParser.ComputeSlug(r.ParsedName);
				if (slug.Length == 0)
				{
					continue;
				}

				checkedCount++;
				if (!IngredientLineResolver.ShouldReuse(slug, r.HoldoutId.Length >= 0 ? ReuseTargetOf(r) : string.Empty))
				{
					shouldReuseFalse++;
				}
			}

			writers.Error.WriteLine($"reuse lines where ShouldReuse(parsedName, linkedIngredientId) is false: {shouldReuseFalse}/{checkedCount}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			writers.Error.WriteLine($"row-choice-tier: key higher={tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} accepted higher={tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff: {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private static string AtomPathOf(TraceLine line) => line.Atoms.Count > 0 ? line.Atoms[0].Path : string.Empty;

	// The reuse target is the linked master slug; the TSV does not carry it, so the summary re-reads
	// it from the trace line the result was built from.
	private static string ReuseTargetOf(ClassificationResult r) => r.ParsedName;

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static IReadOnlyList<string> FoldName(string name) =>
		Array.ConvertAll(FdcNormalizerSingleton.Normalize(name).ToArray(), t => IngredientLineResolver.SingularizeToken(t));

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\r', ' ').Replace('\n', ' ');

	private static async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		await foreach (var raw in File.ReadLinesAsync(path).WithCancellation(cancellationToken).ConfigureAwait(false)
		{
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions)
					?? throw new InvalidOperationException("trace line deserialized to null"));
			}
			catch (JsonException ex)
			{
				Console.Error.WriteLine($"trace parse error in {path}: {ex.Message}");
				return null;
			}
		}

		return lines;
	}

	private static IEnumerable<CensusRow> ReadCensusRows(string path)
	{
		var header = File.ReadLines(path).First().Split('\t');
		var id = Array.IndexOf(header, "holdoutId");
		var idx = Array.IndexOf(header, "lineIndex");
		var blocker = Array.IndexOf(header, "blocker");
		var route = Array.IndexOf(header, "route");
		if (id < 0 || idx < 0 || blocker < 0 || route < 0)
		{
			throw new InvalidOperationException($"census tsv {path} is missing holdoutId/lineIndex/blocker/route columns");
		}

		foreach (var raw in File.ReadLines(path).Skip(1))
		{
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			var cells = raw.Split('\t');
			yield return new CensusRow(
				cells[id],
				int.Parse(cells[idx], CultureInfo.InvariantCulture),
				cells[blocker],
				cells[route]);
		}
	}

	private sealed record CensusRow(string HoldoutId, int LineIndex, string Blocker, string Route);
}
